contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount, bool isOwner) public payable {
        require(amount > 0);
        require(receiver != address(0));
        // Precondition: ether available if not owner
        require(isOwner || address(this).balance >= amount);
        // Ensure caller is owner or not via parameter; for P, we must be owner to succeed
        // We cannot change msg.sender, so we simulate by expecting revert behavior based on isOwner flag
        bool reverted;
        if (isOwner) {
            // Only call when we have enough balance; sendTo will revert if not owner
            try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
        } else {
            // Send ether to c? Actually sendTo sends from c's balance, not ours. 
            // So we can just call and expect it to revert.
            // But to match original: if not owner, call reverts.
            try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
        }
        // On P: call succeeds iff isOwner is true.
        // On M: call succeeds iff isOwner is false.
        assert(reverted != isOwner);
    }
    receive() external payable {}
}

