pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        vm.assume(amount > 0);
        vm.assume(caller.balance >= amount);
        vm.deal(caller, caller.balance);

        // Deploy a helper that always reverts on receive, distinguishing owner-only vs any-caller behavior
        Reverter rev = new Reverter();
        address target = address(rev);
        vm.deal(target, 0);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(C.sendTo.selector, target, amount)
        );

        // Owner can send (if caller == owner, ok is irrelevant to the property, but we assert that
        // non-owner calls revert: if caller != owner, ok must be false)
        assertTrue(caller == c.owner() ? true : !ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

